//! Contract tests for Discord `<t:…>` timestamps (P7-01e, RW-29 / W29a).
//!
//! Independent oracle: `rust/crates/discord-i18n/tests/data/timestamp-oracle.json`,
//! generated by `waves/RW-29/gen-timestamp-data.mjs` from Node 24 ICU
//! (`Intl.DateTimeFormat` / `Intl.RelativeTimeFormat`, `timeZone: "UTC"`).
//! Expectations are never derived from `timestamp_data.rs`.
//!
//! Договорённости, зафиксированные в тестах (см. `waves/RW-29/REPORT-W29a.md`):
//! - все шесть календарных стилей рендерятся в UTC;
//! - NNBSP/NBSP в оракуле и в рендере нормализованы в обычный пробел;
//! - `f`/`F` собраны ICU из явных компонентов (`f` — короткая дата `d` + короткое
//!   время `t`, `F` — длинная дата с weekday + короткое время), а не из `dateStyle`;
//! - относительный стиль использует `Auto`, поэтому ru `+2 сут` даёт «послезавтра»
//!   (ICU special form), хотя в ТЗ §3 t05 записано «через 2 дня»; приоритет у §1
//!   («`relative::format_relative(.., Auto)`») и оракула.

use discord_i18n::timestamp::{
    TIMESTAMP_LOCALE_COUNT, TIMESTAMP_PATTERN_COUNT, TimestampStyle, render_timestamp,
    render_timestamp_tokens, timestamp_style,
};

const ORACLE: &str = include_str!("data/timestamp-oracle.json");
const NOW: i64 = 1_800_000_000;
const MOMENT: i64 = 1_623_488_460; // 2021-06-12T09:01:00Z

fn oracle() -> discord_json::JsonValue {
    discord_json::parse(ORACLE).expect("oracle fixture is valid JSON")
}

fn style(letter: &str) -> TimestampStyle {
    timestamp_style(letter).unwrap_or_else(|| panic!("unknown oracle style: {letter}"))
}

fn array<'a>(value: &'a discord_json::JsonValue, name: &str) -> &'a [discord_json::JsonValue] {
    value
        .as_object()
        .and_then(|object| object.get(name))
        .and_then(discord_json::JsonValue::as_array)
        .unwrap_or_else(|| panic!("oracle array {name}"))
}

fn string<'a>(value: &'a discord_json::JsonValue, name: &str) -> &'a str {
    value
        .as_object()
        .and_then(|object| object.get(name))
        .and_then(discord_json::JsonValue::as_str)
        .unwrap_or_else(|| panic!("oracle field {name}"))
}

fn integer(value: &discord_json::JsonValue, name: &str) -> i64 {
    value
        .as_object()
        .and_then(|object| object.get(name))
        .and_then(discord_json::JsonValue::as_i64)
        .unwrap_or_else(|| panic!("oracle integer {name}"))
}

fn contains_placeholder(text: &str) -> bool {
    text.contains('{') || text.contains('}')
}

fn contains_nbsp(text: &str) -> bool {
    text.contains('\u{a0}') || text.contains('\u{202f}')
}

#[test]
fn t01_style_codes_map_to_all_seven_styles() {
    for (letter, expected) in [
        ("t", TimestampStyle::ShortTime),
        ("T", TimestampStyle::LongTime),
        ("d", TimestampStyle::ShortDate),
        ("D", TimestampStyle::LongDate),
        ("f", TimestampStyle::ShortDateTime),
        ("F", TimestampStyle::LongDateTime),
        ("R", TimestampStyle::Relative),
    ] {
        assert_eq!(timestamp_style(letter), Some(expected), "код {letter}");
    }
    for invalid in ["", "q", "r", "tt", "RR", "tT", "1", " t", "t ", "🕘"] {
        assert_eq!(timestamp_style(invalid), None, "код {invalid:?}");
    }
}

#[test]
fn t02_en_short_and_long_time_and_date_time() {
    for (letter, expected) in [
        ("t", "9:01 AM"),
        ("T", "9:01:00 AM"),
        ("f", "06/12/2021, 9:01 AM"),
        ("F", "Saturday, June 12, 2021 at 9:01 AM"),
    ] {
        assert_eq!(
            render_timestamp(MOMENT, style(letter), "en-US", 0),
            expected,
            "en-US {letter}"
        );
    }
}

#[test]
fn t03_en_short_and_long_date() {
    assert_eq!(
        render_timestamp(MOMENT, TimestampStyle::ShortDate, "en-US", 0),
        "06/12/2021"
    );
    assert_eq!(
        render_timestamp(MOMENT, TimestampStyle::LongDate, "en-US", 0),
        "June 12, 2021"
    );
}

#[test]
fn t04_ru_all_calendar_styles() {
    for (letter, expected) in [
        ("t", "9:01"),
        ("T", "9:01:00"),
        ("d", "12.06.2021"),
        ("D", "12 июня 2021 г."),
        ("f", "12.06.2021, 9:01"),
        ("F", "суббота, 12 июня 2021 г. в 9:01"),
    ] {
        assert_eq!(
            render_timestamp(MOMENT, style(letter), "ru", 0),
            expected,
            "ru {letter}"
        );
    }
}

#[test]
fn t05_relative_en_and_ru_use_auto_forms() {
    let plus_two_days = NOW + 2 * 86_400;
    let five_minutes_ago = NOW - 5 * 60;
    assert_eq!(
        render_timestamp(plus_two_days, TimestampStyle::Relative, "en-US", NOW),
        "in 2 days"
    );
    assert_eq!(
        render_timestamp(five_minutes_ago, TimestampStyle::Relative, "en-US", NOW),
        "5 minutes ago"
    );
    assert_eq!(
        render_timestamp(NOW, TimestampStyle::Relative, "en-US", NOW),
        "now"
    );
    // ICU Auto для ru имеет формы ±2 сут; ТЗ §3 писал «через 2 дня», но контракт §1
    // требует Auto, а оракул фиксирует «послезавтра».
    assert_eq!(
        render_timestamp(plus_two_days, TimestampStyle::Relative, "ru", NOW),
        "послезавтра"
    );
    assert_eq!(
        render_timestamp(five_minutes_ago, TimestampStyle::Relative, "ru", NOW),
        "5 минут назад"
    );
    assert_eq!(
        render_timestamp(NOW, TimestampStyle::Relative, "ru", NOW),
        "сейчас"
    );
}

#[test]
fn t06_relative_ladder_units_and_truncation() {
    for (delta, expected) in [
        (0, "now"),
        (59, "in 59 seconds"),
        (-59, "59 seconds ago"),
        (60, "in 1 minute"),
        (3_599, "in 59 minutes"),
        (3_600, "in 1 hour"),
        (7_199, "in 1 hour"),
        (86_399, "in 23 hours"),
        (86_400, "tomorrow"),
        (172_800, "in 2 days"),
        (604_799, "in 6 days"),
        (604_800, "next week"),
        (1_814_400, "in 3 weeks"),
        (2_591_999, "in 4 weeks"),
        (2_592_000, "next month"),
        (12_960_000, "in 5 months"),
        (31_535_999, "in 12 months"),
        (31_536_000, "next year"),
        (-31_536_000, "last year"),
        (63_072_000, "in 2 years"),
        (-63_072_000, "2 years ago"),
    ] {
        assert_eq!(
            render_timestamp(NOW + delta, TimestampStyle::Relative, "en-US", NOW),
            expected,
            "delta {delta}"
        );
    }
}

#[test]
fn t07_tokens_are_replaced_left_to_right_and_text_is_preserved() {
    assert_eq!(
        render_timestamp_tokens(
            "A <t:1623488460:t> B <t:1623488460:R> C <t:1623488460:f>",
            "en-US",
            NOW
        ),
        "A 9:01 AM B 5 years ago C 06/12/2021, 9:01 AM"
    );
    assert_eq!(
        render_timestamp_tokens("<t:1:t><t:1:T>", "en-US", NOW),
        "12:00 AM12:00:01 AM"
    );
    assert_eq!(
        render_timestamp_tokens("<t:1623488460>", "en-US", NOW),
        "06/12/2021, 9:01 AM",
        "пустой стиль означает f (ShortDateTime)"
    );
    assert_eq!(
        render_timestamp_tokens("<t:1:t> tail", "en-US", NOW),
        "12:00 AM tail"
    );
    for untouched in [
        "",
        "просто текст с юникодом: Привет 🌍",
        "угловые скобки < > и <t без двоеточия",
        "NBSP\u{a0}и NNBSP\u{202f} сохраняются",
    ] {
        assert_eq!(
            render_timestamp_tokens(untouched, "en-US", NOW),
            untouched,
            "вход без токенов должен вернуться байт-в-байт"
        );
    }
}

#[test]
fn t08_invalid_tokens_are_left_as_is() {
    for invalid in [
        "<t:abc>",
        "<t:1:q>",
        "<t:1:RR>",
        "<t:1:Tt>",
        "<t:>",
        "<t:1",
        "<t:-:t>",
        "<t:+1:t>",
        "<t: 1:t>",
        "<t:1 :t>",
        "<t:1:t",
        "<t:9223372036854775808:t>",
        "<t:-9223372036854775809:t>",
        "<t:1:>",
        "<t::t>",
    ] {
        assert_eq!(
            render_timestamp_tokens(invalid, "en-US", NOW),
            invalid,
            "невалидный токен {invalid:?}"
        );
    }
    assert_eq!(
        render_timestamp_tokens("x <t:abc> y <t:1:t> z", "en-US", NOW),
        "x <t:abc> y 12:00 AM z"
    );
    assert_eq!(
        render_timestamp_tokens("<t:1:t>", "en-US", NOW),
        render_timestamp(1, TimestampStyle::ShortTime, "en-US", NOW)
    );
}

#[test]
fn t09_unknown_and_disabled_locales_fall_back_to_en_us() {
    for letter in ["t", "T", "d", "D", "f", "F"] {
        let expected = render_timestamp(MOMENT, style(letter), "en-US", 0);
        for locale in ["xx", "he", "ar", "id", "pt-PT", "sk", ""] {
            assert_eq!(
                render_timestamp(MOMENT, style(letter), locale, 0),
                expected,
                "локаль {locale:?}, стиль {letter}"
            );
        }
    }
    let relative_expected = render_timestamp(MOMENT, TimestampStyle::Relative, "en-US", NOW);
    assert_eq!(
        render_timestamp(MOMENT, TimestampStyle::Relative, "he", NOW),
        relative_expected
    );
}

#[test]
fn t10_extreme_i64_values_do_not_panic() {
    let min_date = render_timestamp(i64::MIN, TimestampStyle::ShortDate, "en-US", 0);
    assert!(!min_date.is_empty());
    assert_eq!(
        min_date,
        render_timestamp(i64::MIN, TimestampStyle::ShortDate, "en-US", 0),
        "рендер детерминирован"
    );
    let max_long = render_timestamp(i64::MAX, TimestampStyle::LongDateTime, "ru", i64::MIN);
    assert!(!max_long.is_empty());
    assert_eq!(
        max_long,
        render_timestamp(i64::MAX, TimestampStyle::LongDateTime, "ru", i64::MIN)
    );
    assert!(
        !contains_nbsp(&min_date) && !contains_nbsp(&max_long),
        "NBSP/NNBSP нормализованы"
    );

    // Значения экстремумов из оракула: сатурация при вычитании и целочисленное
    // деление без переполнения.
    let document = oracle();
    for case in array(&document, "extreme") {
        let timestamp: i64 = string(case, "timestamp").parse().expect("i64 timestamp");
        let now: i64 = string(case, "now").parse().expect("i64 now");
        assert_eq!(
            render_timestamp(timestamp, TimestampStyle::Relative, "en-US", now),
            string(case, "expected")
        );
    }
    assert_eq!(
        render_timestamp_tokens("<t:-9223372036854775808:R>", "en-US", i64::MAX),
        "292,471,208,677 years ago"
    );
    assert_eq!(
        render_timestamp_tokens("<t:9223372036854775807:R>", "en-US", i64::MIN),
        "in 292,471,208,677 years"
    );
    assert_eq!(
        render_timestamp_tokens("<t:-9223372036854775808:d>", "en-US", 0),
        render_timestamp(i64::MIN, TimestampStyle::ShortDate, "en-US", 0)
    );
}

#[test]
fn t11_oracle_matrix_matches_exactly() {
    let document = oracle();
    let cases = array(&document, "cases");
    assert_eq!(cases.len(), 31 * 6 * 3, "строк оракула");
    for case in cases {
        let locale = string(case, "locale");
        let letter = string(case, "style");
        let timestamp = integer(case, "timestamp");
        assert_eq!(
            render_timestamp(timestamp, style(letter), locale, 0),
            string(case, "expected"),
            "{locale} {letter} {timestamp}"
        );
    }
}

#[test]
fn t12_generated_data_invariants() {
    assert_eq!(TIMESTAMP_LOCALE_COUNT, 31, "включённых локалей");
    assert_eq!(TIMESTAMP_PATTERN_COUNT, 31 * 6, "паттернов");
    let document = oracle();
    let cases = array(&document, "cases");
    assert_eq!(cases.len(), 31 * 6 * 3);
    assert_eq!(array(&document, "styles").len(), 6);
    assert_eq!(array(&document, "locales").len(), 31);

    let mut combinations = std::collections::BTreeSet::new();
    for case in cases {
        let locale = string(case, "locale");
        let letter = string(case, "style");
        let timestamp = integer(case, "timestamp");
        assert!(
            discord_i18n::is_enabled(locale),
            "локаль оракула должна быть включённой: {locale}"
        );
        assert!(timestamp_style(letter).is_some(), "стиль {letter}");
        assert!(
            combinations.insert((locale.to_owned(), letter.to_owned(), timestamp)),
            "дубликат строки {locale} {letter} {timestamp}"
        );
        let expected = string(case, "expected");
        assert!(!expected.is_empty(), "пустая строка {locale} {letter}");
        assert!(
            !contains_placeholder(expected),
            "плейсхолдер в {locale} {letter}: {expected}"
        );
        assert!(
            !contains_nbsp(expected),
            "NBSP/NNBSP не нормализован: {locale} {letter}"
        );
    }
    assert_eq!(combinations.len(), 31 * 6 * 3);
}

#[test]
fn t13_every_enabled_locale_renders_and_disabled_locales_fall_back() {
    let document = oracle();
    let locales = array(&document, "locales");
    assert_eq!(locales.len(), 31);
    let mut languages = std::collections::BTreeSet::new();
    for locale in locales {
        let locale = locale.as_str().expect("oracle locale is a string");
        languages.insert(discord_i18n::locale_language(locale));
        for letter in ["t", "T", "d", "D", "f", "F", "R"] {
            let rendered = render_timestamp(MOMENT, style(letter), locale, NOW);
            assert!(!rendered.is_empty(), "{locale} {letter}");
            assert!(
                !contains_placeholder(&rendered),
                "плейсхолдер: {locale} {letter} → {rendered}"
            );
            assert!(!contains_nbsp(&rendered), "NBSP: {locale} {letter}");
        }
    }
    assert!(languages.len() >= 20, "языков: {languages:?}");
    for disabled in discord_i18n::DISABLED_LOCALES {
        assert!(!discord_i18n::is_enabled(disabled));
        for letter in ["t", "T", "d", "D", "f", "F", "R"] {
            assert_eq!(
                render_timestamp(MOMENT, style(letter), disabled, NOW),
                render_timestamp(MOMENT, style(letter), "en-US", NOW),
                "выключенная локаль {disabled}, стиль {letter}"
            );
        }
    }
}

#[test]
fn t14_relative_oracle_and_ladder_cases_match() {
    let document = oracle();
    let relative = document
        .as_object()
        .and_then(|object| object.get("relative"))
        .expect("oracle relative section");
    let now = integer(relative, "now");
    assert_eq!(now, NOW);
    let cases = array(relative, "cases");
    assert_eq!(cases.len(), 4 * (7 * 2 + 1), "R-кейсов");
    for case in cases {
        let locale = string(case, "locale");
        let delta = integer(case, "delta");
        assert_eq!(
            render_timestamp(now + delta, TimestampStyle::Relative, locale, now),
            string(case, "expected"),
            "{locale} delta {delta}"
        );
    }
    let ladder = array(&document, "ladder");
    assert!(ladder.len() >= 20, "границ ладдера: {}", ladder.len());
    for case in ladder {
        let now = integer(case, "now");
        let timestamp = integer(case, "timestamp");
        assert_eq!(
            render_timestamp(timestamp, TimestampStyle::Relative, "en-US", now),
            string(case, "expected"),
            "ладдер delta {}",
            integer(case, "delta")
        );
    }
}
